= Route111_EventScript_RockSmashTipFatMan
lockall
applymovement LOCALID_ROUTE111_ROCK_SMASH_MAN Common_Movement_FacePlayer
waitmovement 0
msgbox	Oh, no!My uncle in MAUVILLE told me to take ROCK SMASH with me if I was going to ROUTE 111!My uncle? He lives across from the bike shop in MAUVILLE.
closemessage
applymovement LOCALID_ROUTE111_ROCK_SMASH_MAN Common_Movement_FaceOriginalDirection
waitmovement 0
releaseall
end
= Route111_EventScript_Hiker
lock
faceplayer
goto_if_eq VAR_MIRAGE_TOWER_STATE 3 Route111_EventScript_HikerMirageTowerGone
goto_if_eq VAR_MIRAGE_TOWER_STATE 2 Route111_EventScript_HikerMirageTowerDisintegrated
goto_if_set FLAG_MIRAGE_TOWER_VISIBLE Route111_EventScript_HikerMirageTowerVisible
msgbox	There should be a tower made of sand around here somewhere.But for some reason, it can be seen sometimes, and sometimes not.That's why I call it the MIRAGE TOWER.
release
end
= Route111_EventScript_HikerMirageTowerVisible
msgbox	I see it! The tower of sand!The sand tower they called a mirage is clearly visible!But it looks so fragile… It could crumble away anytime…I want to go inside it, but I can't get my courage up for it…
release
end
= Route111_EventScript_HikerMirageTowerDisintegrated
msgbox	Whoa… That was shocking.Sand rained down in chunks all of a sudden.What was it like inside? Were there sandy ghosts and such?
release
end
= Route111_EventScript_HikerMirageTowerGone
msgbox	Since I spoke to you, the tower of sand hasn't been seen.Perhaps it really was the MIRAGE TOWER…
release
end
= Route111_EventScript_ItemElixir
goto_if_set FLAG_ITEM_ROUTE_111_ELIXIR Route111_EventScript_ItemElixir_Taken
finditem ITEM_ELIXIR
setflag FLAG_ITEM_ROUTE_111_ELIXIR
end
= Route111_EventScript_ItemElixir_Taken
end
= Route111_EventScript_Branden
trainerbattle_single TRAINER_BRANDEN Route111_Text_BrandenIntro Route111_Text_BrandenDefeat
msgbox	My SANDSHREW loves eating my sandwiches.
end
= Route111_EventScript_Celia
trainerbattle_single TRAINER_CELIA Route111_Text_CeliaIntro Route111_Text_CeliaDefeat
msgbox	In a sandstorm like this, I can't set the places for a picnic even with my GO-GOGGLES on…
end
= Route111_EventScript_Bryan
trainerbattle_single TRAINER_BRYAN Route111_Text_BryanIntro Route111_Text_BryanDefeat
msgbox	This desert hoards mysteries in its shifting sands!
end
= Route111_EventScript_Hayden
trainerbattle_single TRAINER_HAYDEN Route111_Text_HaydenIntro Route111_Text_HaydenDefeat
msgbox	My stomach is grumbling! Maybe I can grill some BERRIES…
end
= Route111_EventScript_Bianca
trainerbattle_single TRAINER_BIANCA Route111_Text_BiancaIntro Route111_Text_BiancaDefeat
msgbox	This road here… You have quite a ways to travel.
end
= Route111_EventScript_Celina
trainerbattle_single TRAINER_CELINA Route111_Text_CelinaIntro Route111_Text_CelinaDefeat
msgbox	My pulse is still racing. You're one fabulous TRAINER.
end
= Route111_EventScript_Tyron
trainerbattle_single TRAINER_TYRON Route111_Text_TyronIntro Route111_Text_TyronDefeat
msgbox	When having a battle, I get a kick out of showing off my POKéMON.I bet everyone feels that way when they enter a battle!
end
= Route111_EventScript_Man2
msgbox	I challenged the WINSTRATE family, but four matches in a row is tough going… They destroyed me.
end
= Route111_EventScript_SecretPowerMan
lock
faceplayer
msgbox	Route111_Text_MakingRoomUseTMToMakeYourOwn
goto_if_eq VAR_RESULT YES Route111_EventScript_GiveSecretPower
msgbox	Route111_Text_DontWantThis
release
end
= Route111_EventScript_GiveSecretPower
giveitem ITEM_TM_SECRET_POWER
goto_if_eq VAR_RESULT FALSE Route111_EventScript_NoRoomForSecretPower
msgbox	Route111_Text_ExplainSecretPower
closemessage
setflag FLAG_RECEIVED_SECRET_POWER
clearflag FLAG_HIDE_SLATEPORT_CITY_TM_SALESMAN
call_if_eq VAR_FACING DIR_WEST Route111_EventScript_SecretPowerManExit
call_if_eq VAR_FACING DIR_EAST Route111_EventScript_SecretPowerManExit
call_if_eq VAR_FACING DIR_NORTH Route111_EventScript_SecretPowerManExitNorth
removeobject VAR_LAST_TALKED
release
end
= Route111_EventScript_SecretPowerManExitNorth
applymovement VAR_LAST_TALKED Route111_Movement_SecretPowerManExitNorth
waitmovement 0
return
= Route111_EventScript_SecretPowerManExit
applymovement VAR_LAST_TALKED Route111_Movement_SecretPowerManExit
waitmovement 0
return
= Route111_EventScript_NoRoomForSecretPower
msgbox	Route111_Text_DontHaveAnyRoom
release
end
= Route111_EventScript_Wilton
trainerbattle_single TRAINER_WILTON_1 Route111_Text_WiltonIntro Route111_Text_WiltonDefeat Route111_EventScript_RegisterWilton
specialvar VAR_RESULT ShouldTryRematchBattle
goto_if_eq VAR_RESULT TRUE Route111_EventScript_RematchWilton
msgbox	POKéMON and TRAINERS learn much through battling.What's important is to never give up even if you lose.
release
end
= Route111_EventScript_RematchWilton
trainerbattle_rematch TRAINER_WILTON_1 Route111_Text_WiltonRematchIntro Route111_Text_WiltonRematchDefeat
msgbox	Since you're that strong, you should aim for the POKéMON LEAGUE.
end
= Route111_EventScript_RegisterWilton
special PlayerFaceTrainerAfterBattle
waitmovement 0
msgbox	There is much to be learned from your training style.I request a rematch if it behooves you.
register_matchcall TRAINER_WILTON_1
release
end
= Route111_EventScript_Brooke
trainerbattle_single TRAINER_BROOKE_1 Route111_Text_BrookeIntro Route111_Text_BrookeDefeat Route111_EventScript_RegisterBrooke
specialvar VAR_RESULT ShouldTryRematchBattle
goto_if_eq VAR_RESULT TRUE Route111_EventScript_RematchBrooke
msgbox	I thought I was raising my POKéMON diligently, but, oh no, there is still much to be done.
release
end
= Route111_EventScript_RematchBrooke
trainerbattle_rematch TRAINER_BROOKE_1 Route111_Text_BrookeRematchIntro Route111_Text_BrookeRematchDefeat
msgbox	Maybe I should have stopped my POKéMON from evolving until they learned better moves…
end
= Route111_EventScript_RegisterBrooke
special PlayerFaceTrainerAfterBattle
waitmovement 0
msgbox	I wish I could become friends with more strong people like you!
register_matchcall TRAINER_BROOKE_1
release
end
= Route111_EventScript_Daisuke
trainerbattle_single TRAINER_DAISUKE Route111_Text_DaisukeIntro Route111_Text_DaisukeDefeat
msgbox	All I can do is keep training until I can defeat strong TRAINERS such as yourself.
end
= Route111_EventScript_Travis
trainerbattle_single TRAINER_TRAVIS Route111_Text_TravisIntro Route111_Text_TravisDefeat
msgbox	When I see a TRAINER with a lot of pep, I can't help looking.
end
= Route111_EventScript_Irene
trainerbattle_single TRAINER_IRENE Route111_Text_IreneIntro Route111_Text_IreneDefeat
msgbox	I'm thinking that I should go to MT. CHIMNEY, but the view around here is very nice, too.
end
= EventScript_CutTree
lockall
goto_if_unset FLAG_BADGE01_GET EventScript_CheckTreeCantCut
checkpartymove MOVE_CUT
goto_if_eq VAR_RESULT PARTY_SIZE EventScript_CheckTreeCantCut
setfieldeffectargument 0 VAR_RESULT
bufferpartymonnick STR_VAR_1 VAR_RESULT
buffermovename STR_VAR_2 MOVE_CUT
msgbox	Text_WantToCut
goto_if_eq VAR_RESULT NO EventScript_CancelCut
msgbox	Text_MonUsedFieldMove
closemessage
dofieldeffect FLDEFF_USE_CUT_ON_TREE
waitstate
goto EventScript_CutTreeDown
end
@ Use cut from party menu
goto EventScript_UseCut
= EventScript_UseCut
lockall
dofieldeffect FLDEFF_USE_CUT_ON_TREE
waitstate
goto EventScript_CutTreeDown
end
